import { createMachine, assign } from 'xstate';

type Context = { email: string; error?: string };

export const checkoutMachine = createMachine({
  id: 'checkout',
  initial: 'collecting',
  context: { email: '' } as Context,
  states: {
    collecting: {
      on: {
        SUBMIT: { target: 'validating', actions: assign({ email: ({ event }) => event.email }) },
      },
    },
    validating: {
      invoke: {
        src: fromPromise(async ({ input }: { input: Context }) => {
          const res = await fetch('/api/validate', {
            method: 'POST',
            body: JSON.stringify({ email: input.email }),
          });
          if (!res.ok) throw new Error('Invalid email');
          return true;
        }),
        input: ({ context }) => context,
        onDone: 'confirmed',
        onError: { target: 'collecting', actions: assign({ error: ({ event }) => String(event.error) }) },
      },
    },
    confirmed: { type: 'final' },
  },
});

import { fromPromise } from 'xstate';

import { useMachine } from '@xstate/react';
import { checkoutMachine } from './machines/checkoutMachine';

export function Checkout() {
  const [snapshot, send] = useMachine(checkoutMachine);

  if (snapshot.matches('confirmed')) return <p>Thanks! Confirmation sent.</p>;

  return (
    <form onSubmit={(e) => {
      e.preventDefault();
      const email = new FormData(e.currentTarget).get('email');
      send({ type: 'SUBMIT', email: String(email) });
    }}>
      <input name="email" type="email" required disabled={snapshot.matches('validating')} />
      {snapshot.context.error && <p role="alert">{snapshot.context.error}</p>}
      <button disabled={snapshot.matches('validating')}>
        {snapshot.matches('validating') ? 'Validating…' : 'Submit'}
      </button>
    </form>
  );
}
